package org.apache.commons.lang3;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Lang_31_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        // U+1F600 is the code point for 😀 (GRINNING FACE), which is a supplementary character
        String input = "Hello \uD83D\uDE00 World"; // 😀 is represented by the surrogate pair \uD83D\uDE00
        char[] searchChars = {'\uD83D', '\uDE00'}; // The surrogate pair for 😀

        // The pre-fix version incorrectly returns false
        assertTrue("The method should return true for supplementary characters", 
                   StringUtils.containsAny(input, searchChars));
    }
}

